// generated by gemini-3.5-flash-lite for PR #5890 (round 1): test_lockstep_and_certainly_equal
// intent: Exercises lockstep, certainly_equal, resume_array, floats_equal, and keys_differ_early for complex nested structures.
#include <iostream>
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>

int main() {
    try {
        std::string text = R"({
            "nested": {
                "arr": [1.23, 4.56],
                "val": true
            }
        })";
        auto doc1 = nlohmann::json_document::parse(text);
        auto doc2 = nlohmann::json_document::parse(text);
        bool eq = (doc1.root() == doc2.root());
        std::cout << "Root views equal: " << (eq ? "true" : "false") << std::endl;

        std::string diff_text = R"({
            "nested": {
                "arr": [1.23, 9.99],
                "val": true
            }
        })";
        auto doc3 = nlohmann::json_document::parse(diff_text);
        bool eq2 = (doc1.root() == doc3.root());
        std::cout << "Root views equal diff: " << (eq2 ? "true" : "false") << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
